import warnings; warnings.filterwarnings('ignore')
from scipy.optimize import least_squares
rng=np.random.default_rng(1)
A=np.abs(eps)
def fitfam(name, model, starts):
    best=None
    for p0 in starts:
        try:
            r=least_squares(lambda p: model(p)-sigma, p0, max_nfev=3000)
            if np.all(np.isfinite(r.fun)) and (best is None or r.cost<best.cost): best=r
        except Exception: pass
    print(name, round(np.mean(best.fun**2)/np.var(sigma),6), np.round(best.x,4))
